// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ReentrancyDAO} from "../src/ReentrancyDAO.sol";

contract InvMutTest is Test {
    ReentrancyDAO c;
    function setUp() public { c = new ReentrancyDAO(); }
    function testFuzz_property(address caller, uint256 depositAmount) public {
        vm.assume(caller != address(0) && caller != address(this) && caller != address(c));
        depositAmount = bound(depositAmount, 1, type(uint128).max);
        vm.deal(caller, depositAmount);
        vm.prank(caller);
        c.deposit{value: depositAmount}();
        Reverter reverter = new Reverter();
        vm.deal(address(c), 0);
        vm.deal(address(reverter), depositAmount);
        vm.prank(address(reverter));
        c.deposit{value: depositAmount}();
        uint256 preBalance = address(c).balance;
        vm.prank(address(reverter));
        (bool success, ) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        uint256 expectedTotalCredits = depositAmount * 2;
        assertTrue(address(c).balance == expectedTotalCredits || !success);
    }
}

contract Reverter {
    fallback() external payable {
        revert("intentional revert");
    }
}
